import { workflow, node, trigger, newCredential, expr } from '@n8n/workflow-sdk';

const rodar = trigger({
  type: 'n8n-nodes-base.manualTrigger',
  version: 1,
  config: { name: 'Rodar', position: [0, 0] },
  output: [{}]
});

const montarQueries = node({
  type: 'n8n-nodes-base.code',
  version: 2,
  config: {
    name: 'Montar Queries',
    position: [224, 0],
    parameters: { jsCode: "/* Montar Queries — uma bateria de consultas por canal (whitelabel).\n   Base de cliente = a mesma do relatorio do C6 Lojista (filtro unificado com o\n   Power BI, 28/09), trocando so o whitelabel. No canal de colaboradores (48) o\n   e-mail @c6bank.com NAO sai: la o funcionario e o cliente.\n   O servico MCP corta em 50 linhas por chamada, sem aviso. Nenhuma consulta\n   abaixo passa disso (maior: uf, 28 estados + \"nao identificada\"). */\nconst CANAIS = [\n  { wl: 7,  nome: 'Marketplace Cars2You' },\n  { wl: 48, nome: 'Colaboradores C6' },\n  { wl: 43, nome: 'Canal de vendas C6 Auto' },\n  { wl: 4,  nome: 'Trucks2you' },\n  { wl: 65, nome: 'Lance Fácil BTB Associados' },\n  { wl: 62, nome: 'Lance Fácil BTB' }\n];\n\nconst now = new Date();\nconst pad = (n) => String(n).padStart(2, '0');\nconst ini = new Date(now.getFullYear(), now.getMonth() - 11, 1);\nconst MES_INICIO = ini.getFullYear() + '-' + pad(ini.getMonth() + 1);\nconst fim = new Date(now.getFullYear(), now.getMonth() + 1, 1);\nconst MES_FIM_EXCL = fim.getFullYear() + '-' + pad(fim.getMonth() + 1);\n\nconst UF_CASE = \"CASE WHEN UPPER(TRIM(sa.state)) IN ('SP','MG','PR','SC','RJ','GO','RS','BA','MT','DF','CE','MS','ES','PE','PA','SE','AM','MA','RN','PB','AL','PI','RO','TO','AP','AC','RR') THEN UPPER(TRIM(sa.state)) WHEN UPPER(TRIM(sa.state)) = 'S.P' THEN 'SP' WHEN UPPER(TRIM(sa.state)) = 'RIO DE JANEIRO' THEN 'RJ' WHEN UPPER(TRIM(sa.state)) = 'MATO GROSSO DO SUL' THEN 'MS' WHEN UPPER(TRIM(sa.state)) LIKE 'ESPIRITO%SANTO%' THEN 'ES' ELSE NULL END\";\n\nconst COMPRA = \"advertisement_negotiations an INNER JOIN offers o ON o.id=an.offer_actual_id INNER JOIN advertisements a ON a.id=an.advertisement_id\";\nconst Q = [];\n\nCANAIS.forEach(function (c) {\n  const EXCL = c.wl === 48\n    ? '@cars2you|@datapage|@icarros|@itau|@teste|@dnr|@netcarros|@maisquecliente|@dealersclub'\n    : '@cars2you|@datapage|@icarros|@itau|@teste|@dnr|@netcarros|@maisquecliente|@dealersclub|@c6bank[.]com';\n  const BASE = \"SELECT u.id as user_id FROM users u INNER JOIN user_whitelabels uw ON uw.user_id = u.id AND uw.whitelabel_id = \" + c.wl + \" WHERE u.deleted_at IS NULL AND u.internal_user = 0 AND u.email NOT REGEXP '(\" + EXCL + \")' AND NOT EXISTS(SELECT 1 FROM user_clients_group ucg0 WHERE ucg0.user_id = u.id AND ucg0.client_group_id = 7)\";\n  const IN_BASE = \"(SELECT user_id FROM (\" + BASE + \") bb)\";\n  const push = function (queryName, sql) { Q.push({ queryName: queryName, wl: c.wl, canal: c.nome, database: 'cars2you_production', sql: sql }); };\n  const faixa = function (col) { return \"CASE WHEN DATEDIFF(NOW(), \" + col + \") BETWEEN 0 AND 30 THEN '00-30d' WHEN DATEDIFF(NOW(), \" + col + \") BETWEEN 31 AND 90 THEN '31-90d' WHEN DATEDIFF(NOW(), \" + col + \") BETWEEN 91 AND 180 THEN '91-180d' ELSE '180d+' END\"; };\n\n  push('kpi',\n    \"SELECT \" +\n    \"(SELECT COUNT(*) FROM (\" + BASE + \") t) as total_base, \" +\n    \"(SELECT COUNT(DISTINCT ua.user_id) FROM user_access ua WHERE ua.user_id IN \" + IN_BASE + \") as com_login, \" +\n    \"(SELECT COUNT(DISTINCT o.buyer_user_id) FROM offers o WHERE o.deleted_at IS NULL AND o.buyer_user_id IN \" + IN_BASE + \") as ofertantes, \" +\n    \"(SELECT COUNT(*) FROM offers o WHERE o.deleted_at IS NULL AND o.buyer_user_id IN \" + IN_BASE + \") as total_ofertas, \" +\n    \"(SELECT COUNT(DISTINCT o.buyer_user_id) FROM \" + COMPRA + \" WHERE an.status IN (2,3,7) AND o.buyer_user_id IN \" + IN_BASE + \") as compradores, \" +\n    \"(SELECT COUNT(DISTINCT an.id) FROM \" + COMPRA + \" WHERE an.status IN (2,3,7) AND o.buyer_user_id IN \" + IN_BASE + \") as negociacoes, \" +\n    \"(SELECT SUM(o.price) FROM \" + COMPRA + \" WHERE an.status IN (2,3,7) AND o.buyer_user_id IN \" + IN_BASE + \") as volume, \" +\n    \"(SELECT MAX(an.finish_date_offer) FROM \" + COMPRA + \" WHERE an.status IN (2,3,7) AND o.buyer_user_id IN \" + IN_BASE + \") as ultima_compra\");\n\n  push('situacao',\n    \"SELECT u.situation, COUNT(*) as qtd FROM users u WHERE u.id IN \" + IN_BASE + \" GROUP BY u.situation ORDER BY u.situation\");\n\n  push('recencia',\n    \"SELECT 'login' as tipo, faixa, COUNT(*) as qtd FROM (SELECT \" + faixa('ul') + \" as faixa FROM (SELECT ua.user_id, MAX(ua.created_at) as ul FROM user_access ua WHERE ua.user_id IN \" + IN_BASE + \" GROUP BY ua.user_id) t) x GROUP BY faixa \" +\n    \"UNION ALL \" +\n    \"SELECT 'oferta' as tipo, faixa, COUNT(*) as qtd FROM (SELECT \" + faixa('ul') + \" as faixa FROM (SELECT o.buyer_user_id, MAX(o.created_at) as ul FROM offers o WHERE o.deleted_at IS NULL AND o.buyer_user_id IN \" + IN_BASE + \" GROUP BY o.buyer_user_id) t) x GROUP BY faixa \" +\n    \"UNION ALL \" +\n    \"SELECT 'compra' as tipo, faixa, COUNT(*) as qtd FROM (SELECT \" + faixa('ul') + \" as faixa FROM (SELECT o.buyer_user_id, MAX(an.finish_date_offer) as ul FROM \" + COMPRA + \" WHERE an.status IN (2,3,7) AND o.buyer_user_id IN \" + IN_BASE + \" GROUP BY o.buyer_user_id) t) x GROUP BY faixa\");\n\n  push('evol_login',\n    \"SELECT DATE_FORMAT(ua.created_at,'%Y-%m') as mes, COUNT(DISTINCT ua.user_id) as unicos FROM user_access ua WHERE ua.user_id IN \" + IN_BASE + \" AND ua.created_at >= '\" + MES_INICIO + \"-01' AND ua.created_at < '\" + MES_FIM_EXCL + \"-01' GROUP BY mes ORDER BY mes\");\n  push('evol_oferta',\n    \"SELECT DATE_FORMAT(o.created_at,'%Y-%m') as mes, COUNT(DISTINCT o.buyer_user_id) as unicos FROM offers o WHERE o.deleted_at IS NULL AND o.buyer_user_id IN \" + IN_BASE + \" AND o.created_at >= '\" + MES_INICIO + \"-01' AND o.created_at < '\" + MES_FIM_EXCL + \"-01' GROUP BY mes ORDER BY mes\");\n  push('evol_compra',\n    \"SELECT DATE_FORMAT(an.finish_date_offer,'%Y-%m') as mes, COUNT(DISTINCT o.buyer_user_id) as unicos, COUNT(DISTINCT an.id) as qtd, SUM(o.price) as volume FROM \" + COMPRA + \" WHERE an.status IN (2,3,7) AND o.buyer_user_id IN \" + IN_BASE + \" AND an.finish_date_offer >= '\" + MES_INICIO + \"-01' AND an.finish_date_offer < '\" + MES_FIM_EXCL + \"-01' GROUP BY mes ORDER BY mes\");\n  push('evol_cadastro',\n    \"SELECT DATE_FORMAT(u.created_at,'%Y-%m') as mes, COUNT(*) as qtd FROM users u WHERE u.id IN \" + IN_BASE + \" AND u.created_at >= '\" + MES_INICIO + \"-01' AND u.created_at < '\" + MES_FIM_EXCL + \"-01' GROUP BY mes ORDER BY mes\");\n\n  /* \"novos\" = quem fez aquilo pela PRIMEIRA vez na vida naquele mes */\n  push('nov_login',\n    \"SELECT mes, COUNT(*) as novos FROM (SELECT DATE_FORMAT(MIN(ua.created_at),'%Y-%m') as mes FROM user_access ua WHERE ua.user_id IN \" + IN_BASE + \" GROUP BY ua.user_id) t WHERE mes >= '\" + MES_INICIO + \"' GROUP BY mes ORDER BY mes\");\n  push('nov_oferta',\n    \"SELECT mes, COUNT(*) as novos FROM (SELECT DATE_FORMAT(MIN(o.created_at),'%Y-%m') as mes FROM offers o WHERE o.deleted_at IS NULL AND o.buyer_user_id IN \" + IN_BASE + \" GROUP BY o.buyer_user_id) t WHERE mes >= '\" + MES_INICIO + \"' GROUP BY mes ORDER BY mes\");\n  push('nov_compra',\n    \"SELECT mes, COUNT(*) as novos FROM (SELECT DATE_FORMAT(MIN(an.finish_date_offer),'%Y-%m') as mes FROM \" + COMPRA + \" WHERE an.status IN (2,3,7) AND o.buyer_user_id IN \" + IN_BASE + \" GROUP BY o.buyer_user_id) t WHERE mes >= '\" + MES_INICIO + \"' GROUP BY mes ORDER BY mes\");\n\n  push('top',\n    \"SELECT u.id, u.full_name as nome, (SELECT s.name FROM user_shops us INNER JOIN shops s ON s.id = us.shop_id WHERE us.user_id = u.id ORDER BY us.created_at LIMIT 1) as loja, COUNT(DISTINCT an.id) as compras, SUM(o.price) as valor, MAX(an.finish_date_offer) as ultima FROM \" + COMPRA + \" INNER JOIN users u ON u.id = o.buyer_user_id WHERE an.status IN (2,3,7) AND o.buyer_user_id IN \" + IN_BASE + \" GROUP BY u.id, u.full_name ORDER BY compras DESC LIMIT 10\");\n\n  push('uf',\n    \"SELECT COALESCE(ufn.uf_norm, 'Nao identificada') as uf, COUNT(DISTINCT b.user_id) as qtd FROM (\" + BASE + \") b LEFT JOIN (SELECT DISTINCT us.user_id, \" + UF_CASE + \" as uf_norm FROM user_shops us INNER JOIN shop_addresses sa ON sa.shop_id = us.shop_id AND sa.deleted_at IS NULL) ufn ON ufn.user_id = b.user_id AND ufn.uf_norm IS NOT NULL GROUP BY uf ORDER BY qtd DESC\");\n\n  /* Coorte de cadastro — as definicoes de acesso/oferta/compra sao as mesmas do resto */\n  const BASE_COORTE = \"(\" + BASE.replace(\"SELECT u.id as user_id FROM\", \"SELECT u.id, u.created_at FROM\") + \")\";\n  const D_ACESSO = \"(SELECT ua.user_id AS uid, MIN(ua.created_at) AS d1 FROM user_access ua GROUP BY ua.user_id)\";\n  const D_OFERTA = \"(SELECT o.buyer_user_id AS uid, MIN(o.created_at) AS d1 FROM offers o WHERE o.deleted_at IS NULL GROUP BY o.buyer_user_id)\";\n  const D_COMPRA = \"(SELECT o.buyer_user_id AS uid, MIN(an.finish_date_offer) AS d1 FROM advertisement_negotiations an INNER JOIN offers o ON o.id = an.offer_actual_id WHERE an.status IN (2,3,7) GROUP BY o.buyer_user_id)\";\n  const JOINS = \" FROM \" + BASE_COORTE + \" b LEFT JOIN \" + D_ACESSO + \" ac ON ac.uid = b.id LEFT JOIN \" + D_OFERTA + \" o1 ON o1.uid = b.id LEFT JOIN \" + D_COMPRA + \" c1 ON c1.uid = b.id WHERE b.created_at >= '\" + MES_INICIO + \"-01' GROUP BY mes ORDER BY mes\";\n  const jan = function (alias, pre) {\n    return [30, 60, 90, 180].map(function (n) { return \"SUM(CASE WHEN DATEDIFF(\" + alias + \".d1,b.created_at) <= \" + n + \" THEN 1 ELSE 0 END) AS \" + pre + n; }).join(', ');\n  };\n\n  push('coorte_acum',\n    \"SELECT DATE_FORMAT(b.created_at,'%Y-%m') AS mes, COUNT(*) AS cadastrados, \" +\n    \"SUM(CASE WHEN ac.uid IS NOT NULL THEN 1 ELSE 0 END) AS acessaram, \" +\n    \"SUM(CASE WHEN o1.uid IS NOT NULL THEN 1 ELSE 0 END) AS ofertaram, \" +\n    \"SUM(CASE WHEN c1.uid IS NOT NULL THEN 1 ELSE 0 END) AS compraram, \" +\n    \"SUM(CASE WHEN ac.uid IS NULL THEN 1 ELSE 0 END) AS sem_interacao\" + JOINS);\n  push('coorte_janela',\n    \"SELECT DATE_FORMAT(b.created_at,'%Y-%m') AS mes, COUNT(*) AS cadastrados, \" +\n    jan('ac', 'ac') + \", \" + jan('o1', 'of') + \", \" + jan('c1', 'cp') + \", \" +\n    [30, 60, 90, 180].map(function (n) { return \"SUM(CASE WHEN DATEDIFF(NOW(), b.created_at) >= \" + n + \" THEN 1 ELSE 0 END) AS mad\" + n; }).join(', ') + JOINS);\n});\n\nreturn Q.map(function (q) { return { json: q }; });\n" }
  },
  output: [{}]
});

const mcpRun = node({
  type: '@n8n/n8n-nodes-langchain.mcpClient',
  version: 1.1,
  config: {
    name: 'MCP Run',
    position: [448, 0],
    parameters: {
      serverTransport: 'sse',
      endpointUrl: 'https://mcp-cars2you-readonly.cars2you.com.br/sse',
      authentication: 'bearerAuth',
      tool: { __rl: true, mode: 'id', value: 'run_query', cachedResultName: 'run_query' },
      inputMode: 'json',
      jsonInput: expr("{{ JSON.stringify({ sql: $json.sql, database: $json.database }) }}"),
      options: { timeout: 120000 }
    },
    credentials: { httpBearerAuth: newCredential('MCP Cars2You Readonly - BD SQL', 'Cc8CxzVDwvA3EysZ') }
  },
  output: [{}]
});

const montarHtml = node({
  type: 'n8n-nodes-base.code',
  version: 2,
  config: {
    name: 'Montar HTML',
    position: [672, 0],
    parameters: { jsCode: "/* Montar HTML — junta as respostas do MCP no objeto D e injeta no template.\n   Contrato de entrada (o mesmo dos outros relatorios):\n     $('Montar Queries').all()[i].json = { queryName, wl, ... }\n     $('MCP Run').all()[i].json.structuredContent = { columns: [], rows: [[]] }\n   O template e o HTML da \"Versao A\" com o dado trocado por marcador. Quem\n   desenha e o navegador: o D aqui so carrega numero. */\nconst TEMPLATE = \"<!DOCTYPE html><html lang=\\\"pt-BR\\\"><head><meta charset=\\\"utf-8\\\">\\n<meta name=\\\"viewport\\\" content=\\\"width=device-width,initial-scale=1\\\">\\n<title>Análise de Base de Clientes | Cars2You</title>\\n<script src=\\\"https://cdnjs.cloudflare.com/ajax/libs/Chart.js/4.4.1/chart.umd.js\\\"></script>\\n<style>@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=Oswald:wght@500;600;700&display=swap');\\n:root{--ink:#0f172a;--ink2:#1e293b;--sub:#475569;--faint:#94a3b8;--bg:#f1f5f9;--card:#fff;--line:#e2e8f0;--line-soft:#f1f5f9;--th-bg:#f8fafc;--track:#eef1f6;--row-hover:#f8fafc;--brand:#1e289b;--brand2:#161d73;--brand-soft:#e3e6ff;--good:#047857;--warn:#b45309;--bad:#b91c1c;--amber:#c8791a;--amber2:#e3a13f}\\n*{box-sizing:border-box}\\nbody{margin:0;background:var(--bg);color:var(--ink);font-family:'Inter',-apple-system,'Segoe UI',sans-serif;font-size:13px;line-height:1.6}\\n.page{max-width:1180px;margin:0 auto;padding:0 24px 64px}\\n.header{background:linear-gradient(135deg,var(--brand2) 0%,var(--brand) 100%);margin:0 -24px 0;padding:28px 40px 24px;display:flex;align-items:center;justify-content:space-between;gap:24px;flex-wrap:wrap}\\n.header-left{display:flex;align-items:center;gap:18px}\\n.header-logo{background:#fff;padding:7px 13px;border-radius:7px;display:inline-flex;align-items:center;line-height:0}\\n.header-logo img{height:26px;display:block}\\n.header-divider{width:1px;height:42px;background:rgba(255,255,255,.25)}\\n.header-title h1{font-family:'Oswald',sans-serif;font-size:23px;font-weight:600;color:#fff;letter-spacing:.2px;margin:0}\\n.header-title p{margin:3px 0 0;font-size:11.5px;color:rgba(255,255,255,.72)}\\n.header-meta{display:flex;gap:10px;flex-wrap:wrap;justify-content:flex-end}\\n.pill{background:rgba(255,255,255,.12);border:1px solid rgba(255,255,255,.25);border-radius:20px;padding:5px 14px;font-size:10.5px;font-weight:600;color:rgba(255,255,255,.9)}\\n.header-bar{height:4px;background:linear-gradient(90deg,var(--amber) 0%,var(--amber2) 100%);margin:0 -24px 0}\\n.filtro{background:var(--card);border:1px solid var(--line);border-top:none;border-radius:0 0 10px 10px;margin:0 -24px 32px;padding:16px 40px;display:flex;align-items:center;gap:14px;flex-wrap:wrap}\\n.filtro label{font-family:'Oswald',sans-serif;font-size:11px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--brand2)}\\nselect{font-family:'Inter',sans-serif;font-size:13.5px;font-weight:500;padding:9px 14px;border:1px solid var(--line);border-radius:8px;background:var(--card);color:var(--ink);min-width:290px;cursor:pointer}\\nselect:focus{outline:2px solid var(--brand-soft);border-color:var(--brand)}\\n.fchip{font-size:10.5px;font-weight:600;color:var(--sub);background:var(--brand-soft);border-radius:20px;padding:5px 13px}\\n.sec{margin-bottom:40px}\\n.sec-head{display:flex;align-items:baseline;gap:10px;margin-bottom:16px}\\n.sec-title{font-family:'Oswald',sans-serif;font-size:11.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--brand2)}\\n.sec-line{flex:1;height:1px;background:var(--line)}\\n.sec-note{font-size:10.5px;color:var(--faint);margin-top:-8px;margin-bottom:16px;max-width:940px;line-height:1.65}\\n.i{display:inline-flex;align-items:center;justify-content:center;width:14px;height:14px;border-radius:50%;border:1px solid var(--line);color:var(--faint);font-size:9px;font-weight:700;cursor:help;font-style:normal;vertical-align:1px;flex-shrink:0}\\n.i:hover{background:var(--brand2);color:#fff;border-color:var(--brand2)}\\n.kpi-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:10px}\\n.kpi{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:16px 18px;position:relative;overflow:hidden}\\n.kpi:before{content:'';position:absolute;left:0;top:0;bottom:0;width:3px;background:var(--accent,var(--brand))}\\n.kpi-label{font-size:9.5px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--sub);display:flex;align-items:center;gap:5px}\\n.kpi-value{font-family:'Oswald',sans-serif;font-size:26.5px;font-weight:600;color:var(--ink);line-height:1.15;margin:5px 0 3px}\\n.kpi-sub{font-size:10.5px;color:var(--faint)}\\n.card{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:18px 20px}\\n.card-t{font-family:'Oswald',sans-serif;font-size:12.5px;font-weight:600;color:var(--ink);letter-spacing:.02em;display:flex;align-items:center;gap:6px}\\n.card-s{font-size:10.5px;color:var(--faint);margin:2px 0 14px}\\n.grid2{display:grid;grid-template-columns:1fr 1fr;gap:14px}\\n@media(max-width:900px){.grid2{grid-template-columns:1fr}}\\n.chart{position:relative;height:230px}\\n.chart-sm{position:relative;height:190px}\\n.legend{display:flex;flex-wrap:wrap;gap:14px;margin:10px 0 0;font-size:10.5px;color:var(--sub)}\\n.ldot{display:inline-block;width:9px;height:9px;border-radius:2px;margin-right:5px;vertical-align:-1px}\\n.tw{overflow-x:auto;background:var(--card);border:1px solid var(--line);border-radius:10px}\\ntable{width:100%;border-collapse:collapse}\\nth{background:var(--th-bg);color:var(--brand2);font-size:9.5px;font-weight:700;text-transform:uppercase;letter-spacing:.04em;padding:10px 14px;text-align:left;border-bottom:1px solid var(--line);white-space:nowrap}\\nth.gh{text-align:center;background:var(--brand-soft)}\\nth.r,td.r{text-align:right}\\ntd{padding:9px 14px;font-size:12px;border-bottom:1px solid var(--line-soft);color:var(--ink2);white-space:nowrap}\\ntbody tr:hover{background:var(--row-hover)}\\n.mono{font-family:'Oswald',sans-serif;font-weight:500;font-variant-numeric:tabular-nums}\\n.parcial{color:var(--ink)}\\n.pmark{color:var(--amber);font-weight:700;margin-left:2px}\\n.fun{display:flex;flex-direction:column;gap:8px}\\n.fun-r{display:flex;align-items:center;gap:12px}\\n.fun-l{width:104px;font-size:11.5px;color:var(--sub);flex-shrink:0}\\n.fun-b{flex:1;height:28px;background:var(--track);border-radius:6px;overflow:hidden}\\n.fun-f{height:100%;border-radius:6px;display:flex;align-items:center;padding:0 10px;color:#fff;font-family:'Oswald',sans-serif;font-size:12px;font-weight:600}\\n.fun-p{width:118px;text-align:right;font-size:10.5px;color:var(--faint);flex-shrink:0}\\nfooter{margin-top:36px;padding-top:16px;border-top:1px solid var(--line);font-size:10.5px;color:var(--faint);text-align:center}\\n@media print{body{background:#fff}.sec{break-inside:avoid}}</style></head><body><div class=\\\"page\\\">\\n<div class=\\\"header\\\">\\n  <div class=\\\"header-left\\\">\\n    <div class=\\\"header-logo\\\"><img src=\\\"data:image/png;base64,\\\" alt=\\\"Cars2You\\\"></div>\\n    <div class=\\\"header-divider\\\"></div>\\n    <div class=\\\"header-title\\\"><h1>Análise de Base de Clientes</h1>\\n    <p>Visão geral dos canais &middot; Marketplace, Trucks2you, C6 (Auto + Colaboradores), Lance Fácil BTB (+ Associados)</p></div>\\n  </div>\\n  <div class=\\\"header-meta\\\">\\n    <span class=\\\"pill\\\">Gerado em {{DATA}}</span>\\n    <span class=\\\"pill\\\">{{N_CANAIS}} canais &middot; {{TOTAL}} clientes</span>\\n    <span class=\\\"pill\\\">Confidencial</span>\\n  </div>\\n</div>\\n<div class=\\\"header-bar\\\"></div>\\n<div class=\\\"filtro\\\">\\n  <label for=\\\"fwl\\\">Canal</label>\\n  <select id=\\\"fwl\\\">{{OPCOES}}</select>\\n  <span class=\\\"fchip\\\" id=\\\"chipBase\\\">{{TOTAL}} clientes</span>\\n</div>\\n<div id=\\\"app\\\"></div>\\n<footer>Cars2You &middot; dados do sistema em {{DATA}} &middot; uso interno</footer>\\n</div>\\n<script>\\nvar D = /*__DADOS__*/;\\nvar MON=D.MON, MESES=D.meses, SITU=D.SITU, TIPS=D.TIPS;\\nvar BRAND='#1e289b', BRAND2='#161d73', AMBER='#c8791a', AMBER2='#e3a13f', GOOD='#047857', GREY='#cbd5e1';\\nvar GR='#e2e8f0', TK='#94a3b8';\\nfunction br(n){return (Number(n)||0).toLocaleString('pt-BR');}\\nfunction pct1(n){return (Number(n)||0).toFixed(1).replace('.',',');}\\nfunction money(n){n=Number(n)||0;if(n>=1e9)return 'R$ '+(n/1e9).toFixed(2).replace('.',',')+' bi';if(n>=1e6)return 'R$ '+(n/1e6).toFixed(1).replace('.',',')+' mi';if(n>=1e3)return 'R$ '+Math.round(n/1e3)+' mil';return 'R$ '+br(Math.round(n));}\\nfunction fmtD(d){if(!d)return '—';var s=String(d).slice(0,10).split('-');return s.length===3?s[2]+'/'+s[1]+'/'+s[0]:String(d);}\\nfunction esc(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\\\"/g,'&quot;');}\\n/* Largura de barra e valor CSS: sempre PONTO decimal. A virgula fica no texto. */\\nfunction w(q,t){return (t?(Number(q)/Number(t)*100):0).toFixed(1);}\\nfunction ic(k){var t=TIPS[k];return t?' <i class=\\\"i\\\" title=\\\"'+esc(t)+'\\\">i</i>':'';}\\nvar charts=[];\\nfunction destroyCharts(){charts.forEach(function(c){try{c.destroy();}catch(e){}});charts=[];}\\n\\n/* Base, login, lances e volume sao somaveis entre canais. Ofertantes e\\n   compradores NAO: a mesma pessoa pode estar em dois canais e seria contada\\n   duas vezes - por isso o aviso aparece quando o filtro esta em todos. */\\nfunction agrega(sel){\\n  var wls = sel==='todos' ? D.ordem : [sel];\\n  var o={kpi:{base:0,comLogin:0,semLogin:0,ofertantes:0,compradores:0,ofertas:0,negociacoes:0,volume:0,ultima:null},\\n    situacao:{},recencia:{login:{},oferta:{},compra:{}},evolucao:{},volume:{},coorteAcum:{},coorteJanela:{},uf:{},top:[],multi:wls.length>1};\\n  wls.forEach(function(k){\\n    var d=D.canais[k]; if(!d) return;\\n    ['base','comLogin','semLogin','ofertantes','compradores','ofertas','negociacoes','volume'].forEach(function(f){o.kpi[f]+=Number(d.kpi[f])||0;});\\n    if(d.kpi.ultima&&(!o.kpi.ultima||String(d.kpi.ultima)>String(o.kpi.ultima)))o.kpi.ultima=d.kpi.ultima;\\n    Object.keys(d.situacao).forEach(function(s){o.situacao[s]=(o.situacao[s]||0)+d.situacao[s];});\\n    ['login','oferta','compra'].forEach(function(t){Object.keys(d.recencia[t]).forEach(function(f){o.recencia[t][f]=(o.recencia[t][f]||0)+d.recencia[t][f];});});\\n    Object.keys(d.evolucao).forEach(function(m){if(!o.evolucao[m])o.evolucao[m]={};Object.keys(d.evolucao[m]).forEach(function(tp){if(!o.evolucao[m][tp])o.evolucao[m][tp]={qtd:0,novos:0};o.evolucao[m][tp].qtd+=d.evolucao[m][tp].qtd;o.evolucao[m][tp].novos+=d.evolucao[m][tp].novos;});});\\n    Object.keys(d.volume).forEach(function(m){if(!o.volume[m])o.volume[m]={valor:0,qtd:0};o.volume[m].valor+=d.volume[m].valor;o.volume[m].qtd+=d.volume[m].qtd;});\\n    Object.keys(d.coorteAcum).forEach(function(m){var c=d.coorteAcum[m];var a=o.coorteAcum[m]||{mes:m,cadastrados:0,acessaram:0,ofertaram:0,compraram:0,sem_interacao:0};['cadastrados','acessaram','ofertaram','compraram','sem_interacao'].forEach(function(f){a[f]+=Number(c[f])||0;});o.coorteAcum[m]=a;});\\n    Object.keys(d.coorteJanela).forEach(function(m){var c=d.coorteJanela[m];var F=['cadastrados','ac30','ac60','ac90','ac180','of30','of60','of90','of180','cp30','cp60','cp90','cp180','mad30','mad60','mad90','mad180'];var a=o.coorteJanela[m]||{mes:m};F.forEach(function(f){a[f]=(Number(a[f])||0)+(Number(c[f])||0);});o.coorteJanela[m]=a;});\\n    Object.keys(d.uf).forEach(function(u){o.uf[u]=(o.uf[u]||0)+d.uf[u];});\\n    (d.top||[]).forEach(function(t){o.top.push(t);});\\n  });\\n  o.top.sort(function(a,b){return (Number(b.compras)||0)-(Number(a.compras)||0);});\\n  o.top=o.top.slice(0,10);\\n  return o;\\n}\\n\\nfunction sec(t,tip,nota,corpo){return '<div class=\\\"sec\\\"><div class=\\\"sec-head\\\"><div class=\\\"sec-title\\\">'+t+'</div><div class=\\\"sec-line\\\"></div></div>'+(nota?'<div class=\\\"sec-note\\\">'+nota+ic(tip)+'</div>':'')+corpo+'</div>';}\\nfunction kpi(label,valor,sub,cor,tip){return '<div class=\\\"kpi\\\" style=\\\"--accent:'+(cor||BRAND)+'\\\"><div class=\\\"kpi-label\\\">'+label+ic(tip)+'</div><div class=\\\"kpi-value\\\">'+valor+'</div><div class=\\\"kpi-sub\\\">'+(sub||'')+'</div></div>';}\\n\\nfunction barOpts(stacked,horiz){return{responsive:true,maintainAspectRatio:false,indexAxis:horiz?'y':'x',\\n  plugins:{legend:{display:false},tooltip:{mode:'index',intersect:false,callbacks:{label:function(c){return c.dataset.label+': '+br(c.parsed[horiz?'x':'y']);}}}},\\n  scales:{x:{stacked:!!stacked,grid:{color:GR,drawBorder:false},ticks:{color:TK,font:{size:10}},border:{display:false}},\\n          y:{stacked:!!stacked,grid:{color:GR,drawBorder:false},ticks:{color:TK,font:{size:10}},border:{display:false}}}};}\\n\\nfunction render(sel){\\n  destroyCharts();\\n  var d=agrega(sel), k=d.kpi, out='';\\n  document.getElementById('chipBase').textContent = br(k.base)+' clientes';\\n  var aviso = d.multi ? ' Com mais de um canal somado, ofertantes e compradores podem contar a mesma pessoa duas vezes, porque um cliente pode estar em dois canais.' : '';\\n\\n  out += sec('Panorama da Base','base','Números de topo do canal selecionado.'+aviso,\\n    '<div class=\\\"kpi-grid\\\">'+\\n    kpi('Clientes na base',br(k.base),'',BRAND,'base')+\\n    kpi('Com login',br(k.comLogin),pct1(k.base?k.comLogin/k.base*100:0)+'% da base',GOOD,'comLogin')+\\n    kpi('Sem login',br(k.semLogin),pct1(k.base?k.semLogin/k.base*100:0)+'% da base',GREY,'semLogin')+\\n    kpi('Ofertantes',br(k.ofertantes),'',BRAND2,'ofertantes')+\\n    kpi('Compradores',br(k.compradores),'',AMBER,'compradores')+\\n    kpi('Lances dados',br(k.ofertas),'',BRAND2,'ofertas')+\\n    kpi('Compras',br(k.negociacoes),'última em '+fmtD(k.ultima),AMBER,'negociacoes')+\\n    kpi('Volume',money(k.volume),'',GOOD,'volume')+\\n    '</div>');\\n\\n  var F=[['Base',k.base,'#475569'],['Acessaram',k.comLogin,BRAND],['Ofertaram',k.ofertantes,BRAND2],['Compraram',k.compradores,AMBER]];\\n  var fh='<div class=\\\"card\\\"><div class=\\\"fun\\\">';\\n  F.forEach(function(f,i){var ant=i?F[i-1][1]:f[1];\\n    fh+='<div class=\\\"fun-r\\\"><div class=\\\"fun-l\\\">'+f[0]+'</div><div class=\\\"fun-b\\\"><div class=\\\"fun-f\\\" style=\\\"width:'+w(f[1],k.base)+'%;background:'+f[2]+'\\\">'+br(f[1])+'</div></div><div class=\\\"fun-p\\\">'+(i?pct1(ant?f[1]/ant*100:0)+'% da etapa acima':'100%')+'</div></div>';});\\n  fh+='</div></div>';\\n  out += sec('Funil de Conversão','funil','Cada etapa contém a anterior.'+aviso,fh);\\n\\n  out += sec('Cadastros por Situação','situacao','',\\n    '<div class=\\\"card\\\"><div class=\\\"card-t\\\">Distribuição da base por situação cadastral</div>'+\\n    '<div class=\\\"card-s\\\">Cada faixa é exclusiva e a soma fecha o total da base.</div>'+\\n    '<div class=\\\"chart-sm\\\"><canvas id=\\\"cSitu\\\"></canvas></div><div class=\\\"legend\\\" id=\\\"lSitu\\\"></div></div>');\\n\\n  out += sec('Recência — Há Quanto Tempo Sem Agir','recencia','Conta apenas quem já fez a ação ao menos uma vez.',\\n    '<div class=\\\"card\\\"><div class=\\\"card-t\\\">Tempo desde a última ação</div>'+\\n    '<div class=\\\"card-s\\\">Barras empilhadas: cada linha soma 100% de quem já fez aquela ação.</div>'+\\n    '<div class=\\\"chart-sm\\\"><canvas id=\\\"cRec\\\"></canvas></div>'+\\n    '<div class=\\\"legend\\\"><span><span class=\\\"ldot\\\" style=\\\"background:'+GOOD+'\\\"></span>0–30 dias</span><span><span class=\\\"ldot\\\" style=\\\"background:'+BRAND+'\\\"></span>31–90</span><span><span class=\\\"ldot\\\" style=\\\"background:'+AMBER2+'\\\"></span>91–180</span><span><span class=\\\"ldot\\\" style=\\\"background:'+GREY+'\\\"></span>mais de 180</span></div></div>');\\n\\n  out += sec('Evolução Mensal','evolucao','Pessoas diferentes por mês, não ações.',\\n    '<div class=\\\"grid2\\\">'+\\n    '<div class=\\\"card\\\"><div class=\\\"card-t\\\">Acessos por mês</div><div class=\\\"card-s\\\">Parte clara: quem acessou pela primeira vez naquele mês.</div><div class=\\\"chart-sm\\\"><canvas id=\\\"cLogin\\\"></canvas></div>'+\\n    '<div class=\\\"legend\\\"><span><span class=\\\"ldot\\\" style=\\\"background:'+AMBER+'\\\"></span>Novos</span><span><span class=\\\"ldot\\\" style=\\\"background:'+BRAND+'\\\"></span>Recorrentes</span></div></div>'+\\n    '<div class=\\\"card\\\"><div class=\\\"card-t\\\">Ofertas e compras por mês</div><div class=\\\"card-s\\\">Clientes diferentes que ofertaram e que compraram.</div><div class=\\\"chart-sm\\\"><canvas id=\\\"cOfCp\\\"></canvas></div>'+\\n    '<div class=\\\"legend\\\"><span><span class=\\\"ldot\\\" style=\\\"background:'+BRAND2+'\\\"></span>Ofertaram</span><span><span class=\\\"ldot\\\" style=\\\"background:'+AMBER+'\\\"></span>Compraram</span></div></div>'+\\n    '</div>');\\n\\n  out += sec('Volume Financeiro','volumeMes','Valor pago nas compras concluídas em cada mês.',\\n    '<div class=\\\"card\\\"><div class=\\\"card-t\\\">Volume por mês</div><div class=\\\"card-s\\\">Somente compras concluídas.</div><div class=\\\"chart-sm\\\"><canvas id=\\\"cVol\\\"></canvas></div></div>');\\n\\n  out += sec('Novos Cadastrados — O Que Fizeram Depois','coorteAcum','As faixas são exclusivas e somam o total de cada mês: quem comprou aparece só em Compraram.',\\n    '<div class=\\\"card\\\"><div class=\\\"card-t\\\">Entradas na base, por desfecho</div>'+\\n    '<div class=\\\"card-s\\\">Sem limite de prazo — conta se a pessoa fez aquilo em algum momento.</div>'+\\n    '<div class=\\\"chart\\\"><canvas id=\\\"cCoorte\\\"></canvas></div>'+\\n    '<div class=\\\"legend\\\"><span><span class=\\\"ldot\\\" style=\\\"background:'+AMBER+'\\\"></span>Compraram</span><span><span class=\\\"ldot\\\" style=\\\"background:'+BRAND2+'\\\"></span>Ofertaram, sem comprar</span><span><span class=\\\"ldot\\\" style=\\\"background:'+BRAND+'\\\"></span>Só acessaram</span><span><span class=\\\"ldot\\\" style=\\\"background:'+GREY+'\\\"></span>Nunca interagiram</span></div></div>');\\n\\n  var cj=Object.keys(d.coorteJanela).sort(), parcial=false;\\n  if(cj.length){\\n    var jh='<div class=\\\"tw\\\"><table><thead><tr><th rowspan=\\\"2\\\">Mês do cadastro</th><th class=\\\"r\\\" rowspan=\\\"2\\\">Cadastrados</th><th colspan=\\\"4\\\" class=\\\"gh\\\">Acessaram em até</th><th colspan=\\\"4\\\" class=\\\"gh\\\">Ofertaram em até</th><th colspan=\\\"4\\\" class=\\\"gh\\\">Compraram em até</th></tr><tr>';\\n    for(var z=0;z<3;z++) jh+='<th class=\\\"r\\\">30d</th><th class=\\\"r\\\">60d</th><th class=\\\"r\\\">90d</th><th class=\\\"r\\\">180d</th>';\\n    jh+='</tr></thead><tbody>';\\n    cj.slice().reverse().forEach(function(m){var r=d.coorteJanela[m];var tot=Number(r.cadastrados)||0;\\n      /* Mostra sempre o numero real. Quem acessa no dia seguinte ja conta em ate\\n         30 dias - nao precisa esperar o prazo. Se parte da coorte ainda nao\\n         completou a janela, o valor e um piso e ganha asterisco. */\\n      var c=function(v,jan,campo){var comp=Number(r[campo])||0;var faltam=tot-comp;\\n        if(faltam<=0) return '<td class=\\\"r mono\\\">'+br(v)+'</td>';\\n        parcial=true;\\n        return '<td class=\\\"r mono parcial\\\" title=\\\"'+faltam+' de '+tot+' cadastrados ainda não completaram '+jan+' dias, então este número ainda pode subir\\\">'+br(v)+'<span class=\\\"pmark\\\">*</span></td>';};\\n      jh+='<tr><td class=\\\"mono\\\">'+rot(m)+'</td><td class=\\\"r mono\\\"><b>'+br(tot)+'</b></td>'+\\n        c(r.ac30,30,'mad30')+c(r.ac60,60,'mad60')+c(r.ac90,90,'mad90')+c(r.ac180,180,'mad180')+\\n        c(r.of30,30,'mad30')+c(r.of60,60,'mad60')+c(r.of90,90,'mad90')+c(r.of180,180,'mad180')+\\n        c(r.cp30,30,'mad30')+c(r.cp60,60,'mad60')+c(r.cp90,90,'mad90')+c(r.cp180,180,'mad180')+'</tr>';});\\n    jh+='</tbody></table></div>';\\n    var nj='Contado a partir da data do próprio cadastro. Doze colunas não cabem em gráfico legível, então esta fica como tabela.';\\n    if(parcial) nj+=' O asterisco marca mês em que parte dos cadastrados ainda não completou o prazo da coluna: o número já aconteceu e só pode subir.';\\n    out += sec('Velocidade de Ativação por Coorte','coorteJanela',nj,jh);\\n  }\\n\\n  out += sec('Distribuição Geográfica','uf','Estado da loja vinculada ao cliente.',\\n    '<div class=\\\"card\\\"><div class=\\\"card-t\\\">Clientes por estado</div><div class=\\\"card-s\\\">Quem tem loja em mais de um estado aparece em cada um.</div><div class=\\\"chart\\\"><canvas id=\\\"cUf\\\"></canvas></div></div>');\\n\\n  if(d.top.length){\\n    var th='<div class=\\\"tw\\\"><table><thead><tr><th>#</th><th>Cliente</th><th>Loja</th><th class=\\\"r\\\">Compras</th><th class=\\\"r\\\">Valor</th><th class=\\\"r\\\">Última</th></tr></thead><tbody>';\\n    d.top.forEach(function(t,i){th+='<tr><td class=\\\"mono\\\">'+(i+1)+'</td><td>'+esc(t.nome)+'</td><td style=\\\"color:var(--faint)\\\">'+esc(t.loja||'—')+'</td><td class=\\\"r mono\\\">'+br(t.compras)+'</td><td class=\\\"r mono\\\">'+money(t.valor)+'</td><td class=\\\"r mono\\\">'+fmtD(t.ultima)+'</td></tr>';});\\n    th+='</tbody></table></div>';\\n    out += sec('Top 10 Clientes por Compras','top',d.multi?'União dos dez primeiros de cada canal, reordenada. Nomes são dado sensível: não circular fora do time.':'Nomes são dado sensível: não circular fora do time.',th);\\n  }\\n\\n  document.getElementById('app').innerHTML=out;\\n  desenha(d);\\n}\\n\\nfunction rot(m){var N=['Jan','Fev','Mar','Abr','Mai','Jun','Jul','Ago','Set','Out','Nov','Dez'];var p=String(m).split('-');return p.length===2?N[Number(p[1])-1]+'/'+p[0].slice(2):String(m);}\\nfunction serie(obj,campo,sub){return MESES.map(function(m){var r=obj[m];if(!r)return 0;return sub?(Number((r[sub]||{})[campo])||0):(Number(r[campo])||0);});}\\n\\nfunction desenha(d){\\n  var sk=Object.keys(d.situacao).sort();\\n  var CORES={'1':'#94a3b8','2':'#e3a13f','3':'#047857','4':'#b91c1c','5':'#475569','6':'#c8791a'};\\n  if(sk.length){\\n    charts.push(new Chart(document.getElementById('cSitu'),{type:'bar',data:{labels:['Base'],datasets:sk.map(function(s){\\n      return {label:s+' · '+(SITU[s]||'?'),data:[d.situacao[s]],backgroundColor:CORES[s]||BRAND,borderRadius:3};\\n    })},options:barOpts(true,true)}));\\n    document.getElementById('lSitu').innerHTML=sk.map(function(s){\\n      return '<span><span class=\\\"ldot\\\" style=\\\"background:'+(CORES[s]||BRAND)+'\\\"></span>'+(SITU[s]||'?')+': '+br(d.situacao[s])+'</span>';}).join('');\\n  }\\n\\n  var FX=['00-30d','31-90d','91-180d','180d+'], CR=[GOOD,BRAND,AMBER2,GREY];\\n  var linhas=[['login','Parou de logar'],['oferta','Parou de ofertar'],['compra','Parou de comprar']];\\n  charts.push(new Chart(document.getElementById('cRec'),{type:'bar',data:{labels:linhas.map(function(l){return l[1];}),\\n    datasets:FX.map(function(f,i){return {label:f,data:linhas.map(function(l){return d.recencia[l[0]][f]||0;}),backgroundColor:CR[i],borderRadius:3};})},\\n    options:barOpts(true,true)}));\\n\\n  charts.push(new Chart(document.getElementById('cLogin'),{type:'bar',data:{labels:MON,datasets:[\\n    {label:'Novos',data:serie(d.evolucao,'novos','login'),backgroundColor:AMBER,borderRadius:3},\\n    {label:'Recorrentes',data:MESES.map(function(m){var e=(d.evolucao[m]||{}).login||{qtd:0,novos:0};return Math.max(0,(e.qtd||0)-(e.novos||0));}),backgroundColor:BRAND,borderRadius:3}\\n  ]},options:barOpts(true)}));\\n\\n  charts.push(new Chart(document.getElementById('cOfCp'),{type:'bar',data:{labels:MON,datasets:[\\n    {label:'Ofertaram',data:serie(d.evolucao,'qtd','oferta'),backgroundColor:BRAND2,borderRadius:3},\\n    {label:'Compraram',data:serie(d.evolucao,'qtd','compra'),backgroundColor:AMBER,borderRadius:3}\\n  ]},options:barOpts(false)}));\\n\\n  charts.push(new Chart(document.getElementById('cVol'),{type:'bar',data:{labels:MON,datasets:[\\n    {label:'Volume',data:MESES.map(function(m){return (d.volume[m]||{}).valor||0;}),backgroundColor:GOOD,borderRadius:3}\\n  ]},options:(function(){var o=barOpts(false);o.plugins.tooltip.callbacks.label=function(c){return 'Volume: '+money(c.parsed.y);};o.scales.y.ticks.callback=function(v){return money(v);};return o;})()}));\\n\\n  /* Faixas exclusivas: quem comprou nao reaparece em acessou, senao a pilha\\n     passaria do total de cadastrados do mes. */\\n  charts.push(new Chart(document.getElementById('cCoorte'),{type:'bar',data:{labels:MON,datasets:[\\n    {label:'Compraram',data:MESES.map(function(m){var r=d.coorteAcum[m]||{};return Number(r.compraram)||0;}),backgroundColor:AMBER,borderRadius:3},\\n    {label:'Ofertaram, sem comprar',data:MESES.map(function(m){var r=d.coorteAcum[m]||{};return Math.max(0,(Number(r.ofertaram)||0)-(Number(r.compraram)||0));}),backgroundColor:BRAND2,borderRadius:3},\\n    {label:'Só acessaram',data:MESES.map(function(m){var r=d.coorteAcum[m]||{};return Math.max(0,(Number(r.acessaram)||0)-(Number(r.ofertaram)||0));}),backgroundColor:BRAND,borderRadius:3},\\n    {label:'Nunca interagiram',data:MESES.map(function(m){var r=d.coorteAcum[m]||{};return Number(r.sem_interacao)||0;}),backgroundColor:GREY,borderRadius:3}\\n  ]},options:barOpts(true)}));\\n\\n  var ufs=Object.keys(d.uf).sort(function(a,b){return d.uf[b]-d.uf[a];}).slice(0,15);\\n  charts.push(new Chart(document.getElementById('cUf'),{type:'bar',data:{labels:ufs,datasets:[\\n    {label:'Clientes',data:ufs.map(function(u){return d.uf[u];}),backgroundColor:BRAND,borderRadius:3}\\n  ]},options:barOpts(false,true)}));\\n}\\n\\ndocument.getElementById('fwl').addEventListener('change',function(){render(this.value);});\\nrender('todos');\\n</script></body></html>\";\nconst CONST = {\"SITU\": {\"1\": \"Pré cadastrado\", \"2\": \"Para aprovação\", \"3\": \"Aprovado\", \"4\": \"Reprovado\", \"5\": \"Bloqueado\", \"6\": \"Inadimplente\"}, \"TIPS\": {\"base\": \"Todos os clientes do canal, em qualquer situação cadastral. Exclui contas internas da Cars2You e de parceiros de tecnologia. Onde o próprio anunciante é o dono do canal, o e-mail corporativo dele também sai — menos no canal de colaboradores, onde o funcionário é o cliente.\", \"comLogin\": \"Clientes que já entraram na plataforma pelo menos uma vez, considerando todo o histórico.\", \"semLogin\": \"Cadastrados que nunca acessaram. Continuam na base e contam no total.\", \"ofertantes\": \"Clientes que já deram pelo menos um lance, em qualquer loja da plataforma — não apenas nos veículos deste canal.\", \"compradores\": \"Clientes com pelo menos uma compra concluída. Considera negociação vendida, aguardando pagamento ou aguardando confirmação.\", \"ofertas\": \"Total de lances dados, não de pessoas. Um mesmo cliente aparece quantas vezes tiver ofertado.\", \"negociacoes\": \"Quantidade de compras concluídas, contando cada negociação uma vez.\", \"volume\": \"Soma do valor pago nas compras concluídas. É dado financeiro do sistema, não estimativa.\", \"situacao\": \"Situação do cadastro no momento da consulta. Aprovado é quem pode operar; os demais estão em alguma etapa de análise, bloqueio ou recusa.\", \"funil\": \"Cada etapa contém a anterior: quem comprou também ofertou e acessou. O percentual compara com a etapa imediatamente acima, para mostrar onde está o estrangulamento.\", \"recencia\": \"Há quanto tempo cada cliente fez aquilo pela última vez. Conta apenas quem já fez a ação ao menos uma vez — quem nunca logou não entra na coluna de login.\", \"evolucao\": \"Pessoas diferentes por mês, não ações. A parte clara da barra é quem fazia aquilo pela primeira vez naquele mês.\", \"volumeMes\": \"Valor pago nas compras concluídas em cada mês.\", \"coorteAcum\": \"De cada grupo que entrou na base no mês, o que aconteceu depois. As faixas são exclusivas e somam o total do mês: quem comprou aparece só em Compraram, não também em Acessaram.\", \"coorteJanela\": \"O mesmo grupo, contando só o que aconteceu dentro de 30, 60, 90 e 180 dias do próprio cadastro. Serve para comparar meses em pé de igualdade — quem entrou em janeiro teve mais tempo de converter do que quem entrou no mês passado.\", \"uf\": \"Estado da loja vinculada ao cliente. Quem tem loja em mais de um estado aparece em cada um, então a soma passa do total da base.\", \"top\": \"Os dez clientes com mais compras concluídas, em todo o período.\"}, \"nomes\": {\"4\": \"Trucks2you\", \"7\": \"Marketplace Cars2You\", \"43\": \"Canal de vendas C6 Auto\", \"48\": \"Colaboradores C6\", \"62\": \"Lance Fácil BTB\", \"65\": \"Lance Fácil BTB Associados\"}};\n\nconst qs = $('Montar Queries').all().map(function (i) { return i.json; });\nconst outs = $('MCP Run').all().map(function (i) { return i.json; });\nif (qs.length !== outs.length) throw new Error('Consultas (' + qs.length + ') e respostas (' + outs.length + ') nao batem');\n\nconst num = function (v) { return v == null ? 0 : (typeof v === 'number' ? v : Number(v) || 0); };\n\n/* zip: colunas x linhas -> objetos. Resposta sem structuredContent = a consulta\n   falhou; melhor parar aqui do que publicar um relatorio com furo. */\nfunction dados(wl, nome) {\n  const r = [];\n  qs.forEach(function (q, i) {\n    if (q.wl !== wl || q.queryName !== nome) return;\n    const sc = outs[i].structuredContent;\n    if (!sc || !sc.columns || !sc.rows) {\n      throw new Error('Consulta ' + nome + ' (canal ' + wl + ') sem resposta: ' + JSON.stringify(outs[i]).slice(0, 300));\n    }\n    sc.rows.forEach(function (row) {\n      const o = {}; sc.columns.forEach(function (c, k) { o[c] = row[k]; }); r.push(o);\n    });\n  });\n  return r;\n}\n\n/* 12 meses, do mais antigo ao corrente */\nconst now = new Date();\nconst pad = function (n) { return String(n).padStart(2, '0'); };\nconst NOMES_MES = ['Jan', 'Fev', 'Mar', 'Abr', 'Mai', 'Jun', 'Jul', 'Ago', 'Set', 'Out', 'Nov', 'Dez'];\nconst meses = [], MON = [];\nfor (let k = 11; k >= 0; k--) {\n  const d = new Date(now.getFullYear(), now.getMonth() - k, 1);\n  meses.push(d.getFullYear() + '-' + pad(d.getMonth() + 1));\n  MON.push(NOMES_MES[d.getMonth()] + '/' + String(d.getFullYear()).slice(2));\n}\n\nconst canais = {};\nconst ids = [];\nqs.forEach(function (q) { if (ids.indexOf(q.wl) < 0) ids.push(q.wl); });\n\nids.forEach(function (wl) {\n  const k = dados(wl, 'kpi')[0] || {};\n  const base = num(k.total_base), comLogin = num(k.com_login);\n  const c = {\n    kpi: {\n      base: base, comLogin: comLogin, semLogin: base - comLogin,\n      ofertantes: num(k.ofertantes), compradores: num(k.compradores),\n      ofertas: num(k.total_ofertas), negociacoes: num(k.negociacoes),\n      volume: num(k.volume), ultima: k.ultima_compra || null\n    },\n    situacao: {}, recencia: { login: {}, oferta: {}, compra: {} },\n    evolucao: {}, volume: {}, coorteAcum: {}, coorteJanela: {}, uf: {}, top: []\n  };\n\n  dados(wl, 'situacao').forEach(function (r) { c.situacao[String(r.situation)] = num(r.qtd); });\n  dados(wl, 'recencia').forEach(function (r) { if (c.recencia[r.tipo]) c.recencia[r.tipo][r.faixa] = num(r.qtd); });\n\n  /* evolucao: so entra o mes em que houve atividade (o navegador trata ausente como zero) */\n  const evo = function (m, tipo) { if (!c.evolucao[m]) c.evolucao[m] = {}; if (!c.evolucao[m][tipo]) c.evolucao[m][tipo] = { qtd: 0, novos: 0 }; return c.evolucao[m][tipo]; };\n  dados(wl, 'evol_login').forEach(function (r) { evo(r.mes, 'login').qtd = num(r.unicos); });\n  dados(wl, 'evol_oferta').forEach(function (r) { evo(r.mes, 'oferta').qtd = num(r.unicos); });\n  dados(wl, 'evol_compra').forEach(function (r) {\n    evo(r.mes, 'compra').qtd = num(r.unicos);\n    c.volume[r.mes] = { valor: num(r.volume), qtd: num(r.qtd) };\n  });\n  dados(wl, 'evol_cadastro').forEach(function (r) { evo(r.mes, 'cadastro').qtd = num(r.qtd); });\n  dados(wl, 'nov_login').forEach(function (r) { if (c.evolucao[r.mes] && c.evolucao[r.mes].login) c.evolucao[r.mes].login.novos = num(r.novos); });\n  dados(wl, 'nov_oferta').forEach(function (r) { if (c.evolucao[r.mes] && c.evolucao[r.mes].oferta) c.evolucao[r.mes].oferta.novos = num(r.novos); });\n  dados(wl, 'nov_compra').forEach(function (r) { if (c.evolucao[r.mes] && c.evolucao[r.mes].compra) c.evolucao[r.mes].compra.novos = num(r.novos); });\n\n  dados(wl, 'coorte_acum').forEach(function (r) {\n    c.coorteAcum[r.mes] = { wl: wl, mes: r.mes, cadastrados: num(r.cadastrados), acessaram: num(r.acessaram), ofertaram: num(r.ofertaram), compraram: num(r.compraram), sem_interacao: num(r.sem_interacao) };\n  });\n  dados(wl, 'coorte_janela').forEach(function (r) {\n    const o = { wl: wl, mes: r.mes };\n    Object.keys(r).forEach(function (f) { if (f !== 'mes') o[f] = num(r[f]); });\n    c.coorteJanela[r.mes] = o;\n  });\n  dados(wl, 'uf').forEach(function (r) { c.uf[r.uf] = num(r.qtd); });\n  dados(wl, 'top').forEach(function (r) {\n    c.top.push({ loja: r.loja || null, nome: r.nome, valor: num(r.valor), ultima: r.ultima || null, compras: num(r.compras) });\n  });\n  canais[wl] = c;\n});\n\n/* canais do maior para o menor; o rotulo do seletor leva o tamanho da base */\nconst nomes = {};\nids.forEach(function (wl) { const q = qs.find(function (x) { return x.wl === wl; }); nomes[wl] = q.canal; });\nconst ordem = ids.slice().sort(function (a, b) { return canais[b].kpi.base - canais[a].kpi.base; });\nconst D = { ordem: ordem.map(String), nomes: nomes, canais: canais, MON: MON, meses: meses, SITU: CONST.SITU, TIPS: CONST.TIPS };\n\nconst br = function (n) { return Number(n).toLocaleString('pt-BR'); };\nconst total = ordem.reduce(function (s, wl) { return s + canais[wl].kpi.base; }, 0);\nconst opcoes = '<option value=\"todos\">Todos os canais</option>' + ordem.map(function (wl) {\n  return '<option value=\"' + wl + '\">' + nomes[wl] + ' &middot; ' + br(canais[wl].kpi.base) + '</option>';\n}).join('');\nconst dataTxt = pad(now.getDate()) + '/' + pad(now.getMonth() + 1) + '/' + now.getFullYear();\n\n/* \"<\" vira < dentro do JSON: nome de loja com </script> nao fecha a tag antes da hora */\nconst dadosJson = JSON.stringify(D).split('<').join('\\\\u003c');\nlet html = TEMPLATE\n  .split('{{DATA}}').join(dataTxt)\n  .split('{{N_CANAIS}}').join(String(ordem.length))\n  .split('{{TOTAL}}').join(br(total))\n  .split('{{OPCOES}}').join(opcoes);\nhtml = html.replace('/*__DADOS__*/', function () { return dadosJson; });\n\nreturn [{ json: { html: html, total: total, canais: ordem.map(function (wl) { return nomes[wl] + ': ' + canais[wl].kpi.base; }) } }];\n" }
  },
  output: [{}]
});

const anexarHtml = node({
  type: 'n8n-nodes-base.code',
  version: 2,
  config: {
    name: 'Anexar HTML',
    position: [896, 0],
    parameters: { jsCode: "const html = $json.html;\nconst buff = Buffer.from(html, 'utf8');\nconst now = new Date();\nconst p = (n) => String(n).padStart(2,'0');\nconst fileName = 'Analise_base_geral_clientes_' + now.getFullYear() + '-' + p(now.getMonth()+1) + '-' + p(now.getDate()) + '.html';\nreturn { json: {}, binary: { html: { data: buff.toString('base64'), mimeType: 'text/html', fileName: fileName, fileExtension: 'html' } } };" }
  },
  output: [{}]
});

const enviar = node({
  type: 'n8n-nodes-base.microsoftOutlook',
  version: 2,
  config: {
    name: 'Enviar para Thomas',
    position: [1120, 0],
    parameters: {
      toRecipients: 'thomas.lima@cars2you.com.br',
      subject: expr("{{ 'Análise de Base de Clientes - 6 canais - ' + $now.toFormat('dd/MM/yyyy') }}"),
      bodyContent: "=Olá,\n\nSegue em anexo a Análise de Base de Clientes (6 canais: Marketplace Cars2You, Colaboradores C6, Canal de vendas C6 Auto, Trucks2you e Lance Fácil BTB), com KPIs, funil, recência, evolução mensal, coortes de cadastro, distribuição geográfica e ranking de compradores. Abra o arquivo no navegador e use o seletor de canal no topo.\n\nAutomação Cars2You",
      additionalFields: { attachments: { attachments: [{ binaryPropertyName: 'html' }] } }
    },
    credentials: { microsoftOutlookOAuth2Api: newCredential('Microsoft Outlook Power BI/Automações', 'G3MiTRT9jTVPx6Wn') }
  },
  output: [{}]
});

export default workflow('analise-base-geral-thomas', 'Análise de Base de Clientes - 6 canais (Thomas)')
  .add(rodar)
  .to(montarQueries)
  .to(mcpRun)
